  @objc public func authentication(
    _ authSession: AuthSession,
    request: NSMutableURLRequest,
    finishedWithError error: NSError?
  ) {
    passedAuthorization = authSession
    passedRequest = request
    passedError = error

    expectation.fulfill()
  }
